require"active_support/core_ext/time/calculations";module ActiveSupport;class FileUpdateChecker;def initialize(files,dirs={},&block)unless block;raise ArgumentError,"A block is required to initialize a FileUpdateChecker";end;@files=files.freeze;@glob=compile_glob(dirs);@block=block;@watched=nil;@updated_at=nil;@last_watched=watched;@last_update_at=updated_at(@last_watched);end;def updated?;current_watched=watched;if @last_watched.size!=current_watched.size;@watched=current_watched;true;else current_updated_at=updated_at(current_watched);if @last_update_at<current_updated_at;@watched=current_watched;@updated_at=current_updated_at;true;else false;end;end;end;def execute;@last_watched=watched;@last_update_at=updated_at(@last_watched);@block.call;ensure @watched=nil;@updated_at=nil;end;def execute_if_updated;if updated?;yield if block_given?;execute;true;else false;end;end;private;def watched;@watched||begin all=@files.select{|f|File.exist?(f)};all.concat(Dir[@glob]) if @glob;all.tap(&:uniq!);end;end;def updated_at(paths)@updated_at||max_mtime(paths)||Time.at(0);end;def max_mtime(paths)time_now=Time.at(0,Process.clock_gettime(Process::CLOCK_REALTIME,:nanosecond),:nanosecond);max_mtime=nil;paths.each do |path|mtime=File.mtime(path);next if time_now.compare_without_coercion(mtime)<0;if max_mtime.nil?||max_mtime.compare_without_coercion(mtime)<0;max_mtime=mtime;end;end;max_mtime;end;def compile_glob(hash)hash.freeze
